nextflow_process {

    name "Test Process SEQKIT_SEQ"
    script "../main.nf"
    process "SEQKIT_SEQ"
    config './nextflow.config'

    tag "modules"
    tag "modules_nfcore"
    tag "seqkit"
    tag "seqkit/seq"

    test("sarscov2-genome_fasta") {
        when {
            params {
                modules_args2 = '-n'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("sarscov2-genome_fasta_gz") {
        when {
            params {
                modules_args2 = '-n'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.gz', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("sarscov2-test_1_fastq_gz") {
        when {
            params {
                modules_args2 = '-n'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("file_name_conflict-fail_with_error") {
        when {
            params {
                modules_args2 = '-n'
            }
            process {
                """
                input[0] = [
                    [ id:'test_1' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.failed
            assertAll(
                { assert process.stdout.toString().contains("Input and output names are the same") }
            )
        }
    }

    test("sarscov2-genome_fasta-stub") {
        options '-stub'

        when {
            params {
                modules_args2 = '-n'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("file_name_conflict-fail_with_error-stub") {
        options '-stub'

        when {
            params {
                modules_args2 = '-n'
            }
            process {
                """
                input[0] = [
                    [ id:'genome' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.failed
            assertAll(
                { assert process.stdout.toString().contains("Input and output names are the same") }
            )
        }
    }
}
